import{_ as l,o as t,c as a,a2 as e}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Token 经济","description":"Hearth 的预算层级、Token Governor、Context Compiler、模型阶梯、缓存、硬预算、成本归因与默认策略。","frontmatter":{"title":"Token 经济","description":"Hearth 的预算层级、Token Governor、Context Compiler、模型阶梯、缓存、硬预算、成本归因与默认策略。","outline":[2,3]},"headers":[],"relativePath":"architecture/token-economics.md","filePath":"architecture/token-economics.md","lastUpdated":1793706118000}'),o={name:"architecture/token-economics.md"};function n(r,i,d,s,h,c){return t(),a("div",null,[...i[0]||(i[0]=[e(`<p class="eyebrow">TOKEN ECONOMICS</p><h1 id="token-经济" tabindex="-1">Token 经济 <a class="header-anchor" href="#token-经济" aria-label="Permalink to &quot;Token 经济&quot;">​</a></h1><p class="lead">目标不是单纯少用 Token，而是让每次有效完成更省。Token 是架构约束，不是事后账单。</p><h2 id="token-经济-1" tabindex="-1">Token 经济 <a class="header-anchor" href="#token-经济-1" aria-label="Permalink to &quot;Token 经济&quot;">​</a></h2><p>目标不是“少用 Token”，而是“每次有效完成更省”。Token、成本、延迟和人工分钟必须一起看，不能通过降低质量制造虚假节省。</p><h3 id="预算层级" tabindex="-1">预算层级 <a class="header-anchor" href="#预算层级" aria-label="Permalink to &quot;预算层级&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全局日预算</span></span>
<span class="line"><span>  → 用户/项目预算</span></span>
<span class="line"><span>  → Task 预算</span></span>
<span class="line"><span>  → Run 预算</span></span>
<span class="line"><span>  → Step 预算</span></span>
<span class="line"><span>  → 单次上下文注入预算</span></span>
<span class="line"><span>  → 输出 Token 预算</span></span></code></pre></div><p>预算包括 Token、成本、时间、工具调用次数、网络请求和人工打断。任何一级耗尽都必须暂停、降级或转人工，不能静默透支。</p><h3 id="token-governor" tabindex="-1">Token Governor <a class="header-anchor" href="#token-governor" aria-label="Permalink to &quot;Token Governor&quot;">​</a></h3><p>Token Governor 是跨执行器的成本控制面：</p><ul><li>规则优先：不需要模型的任务直接走确定性路径；</li><li>任务分类：判断任务族、复杂度、风险和隐私级别；</li><li>模型目录：维护能力、价格、延迟、上下文和可用性；</li><li>Context Compiler：构建最小充分上下文；</li><li>Router：按预期成功率/成本选择执行器；</li><li>Cache：复用解析、检索、摘要和已验证产物；</li><li>Meter：实时记录输入、输出、缓存和工具开销；</li><li>Watchdog：发现异常消耗、循环和预算超支；</li><li>Attribution：把成本归因到任务、项目、技能和执行器。</li></ul><h3 id="context-compiler" tabindex="-1">Context Compiler <a class="header-anchor" href="#context-compiler" aria-label="Permalink to &quot;Context Compiler&quot;">​</a></h3><p>Context Compiler 把“系统知道的一切”压缩成“这次任务真正需要的证据”。Context Pack 通常包含：</p><ol><li>目标和验收标准；</li><li>当前任务状态；</li><li>用户明确约束和偏好；</li><li>相关事实与来源引用；</li><li>必要文件片段和 artifact 引用；</li><li>可用工具和权限；</li><li>输出 schema；</li><li>预算和截止时间；</li><li>已知失败和禁止路径；</li><li>需要人决策的问题。</li></ol><p>规则：</p><ul><li>不把完整聊天历史当上下文；</li><li>不把完整邮箱、仓库或网页塞入；</li><li>长材料先索引、分页、检索和摘要；</li><li>只保留有来源的断言；</li><li>用稳定前缀和缓存友好结构复用系统提示；</li><li>摘要不能丢掉关键限定条件、数字和引用；</li><li>任务结束后清理 Working Memory。</li></ul><h3 id="模型与执行器阶梯" tabindex="-1">模型与执行器阶梯 <a class="header-anchor" href="#模型与执行器阶梯" aria-label="Permalink to &quot;模型与执行器阶梯&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>能力</th><th>典型用途</th><th>成本策略</th></tr></thead><tbody><tr><td>T0 确定性</td><td>规则、SQL、脚本、API、diff</td><td>过滤、转换、对账、读取</td><td>不调用模型</td></tr><tr><td>T1 本地分类器</td><td>小模型、embedding、规则模型</td><td>分类、优先级、实体识别</td><td>本地、低延迟</td></tr><tr><td>T2 小模型</td><td>短上下文、结构化输出</td><td>摘要、提取、短草稿</td><td>按量、严格上限</td></tr><tr><td>T3 Native 大模型</td><td>通用推理与工具</td><td>短链路规划、复杂分类</td><td>中等成本</td></tr><tr><td>T4 Codex</td><td>长链路、多文件、复杂产物</td><td>代码、研究、长文档</td><td>高成本、强验证</td></tr><tr><td>T5 Human</td><td>判断、责任、接管</td><td>高风险、歧义、不可逆</td><td>最稀缺，需预算</td></tr></tbody></table><p>路由按任务形态、历史成功率、隐私和成本动态选择，不按工具偏好。</p><h3 id="增量读取" tabindex="-1">增量读取 <a class="header-anchor" href="#增量读取" aria-label="Permalink to &quot;增量读取&quot;">​</a></h3><p>优先使用文件 diff 和版本比较、增量同步和游标、按页/段/表/行检索、文档索引和引用定位、结构化字段提取、重复材料摘要、artifact 引用、相关代码文件和测试结果、网页可访问性树和页面 diff。</p><h3 id="缓存、批处理与本地模型" tabindex="-1">缓存、批处理与本地模型 <a class="header-anchor" href="#缓存、批处理与本地模型" aria-label="Permalink to &quot;缓存、批处理与本地模型&quot;">​</a></h3><ul><li>缓存解析、检索、摘要、embedding 和已验证产物；</li><li>能批量聚合的低价值任务不逐条调用大模型；</li><li>隐私敏感、低延迟或离线任务优先本地模型；</li><li>本地模型不是免费：仍要计算延迟、维护和质量成本；</li><li>缓存必须有版本、失效和删除策略，不能复活已遗忘内容。</li></ul><h3 id="硬预算与异常停止" tabindex="-1">硬预算与异常停止 <a class="header-anchor" href="#硬预算与异常停止" aria-label="Permalink to &quot;硬预算与异常停止&quot;">​</a></h3><ul><li>每级预算有硬上限；</li><li>循环、重复工具调用和异常上下文增长触发 Watchdog；</li><li>预算耗尽后暂停或降级，不静默继续；</li><li>用户能查看“为什么花这么多”；</li><li>人工打断也是成本；</li><li>高风险任务不能为了省预算跳过验证。</li></ul><h3 id="成本归因与指标" tabindex="-1">成本归因与指标 <a class="header-anchor" href="#成本归因与指标" aria-label="Permalink to &quot;成本归因与指标&quot;">​</a></h3><ul><li>每任务、项目、执行器、模型、技能和用户可见动作的成本；</li><li>Verified Success per dollar；</li><li>Token per verified task；</li><li>人工分钟与 Token 的联合下降；</li><li>缓存命中、重复读取和无效重试；</li><li>异常消耗和预算停止次数。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>只优化 Token，不优化人工分钟和成功率；</li><li>用更小模型反复失败；</li><li>把所有记忆和全文塞入上下文；</li><li>用自然语言摘要替代结构化提取；</li><li>重试不设上限；</li><li>缓存污染；</li><li>隐藏成本；</li><li>为省模型调用跳过验证或审批。</li></ul><h3 id="默认策略" tabindex="-1">默认策略 <a class="header-anchor" href="#默认策略" aria-label="Permalink to &quot;默认策略&quot;">​</a></h3><ol><li>能规则/脚本就不调用模型；</li><li>能结构化就不生成自然语言；</li><li>能引用 artifact 就不重复全文；</li><li>能小模型就不大模型；</li><li>能缓存就不重复；</li><li>能停止就不过度重试；</li><li>能转人工就不做高风险无人值守。</li></ol>`,31)])])}const k=l(o,[["render",n]]);export{u as __pageData,k as default};
